// Message format: /buy THYAO.IS 100 285.50 [fee]  or  /sell AAPL 10 190.2
const text = String($input.first().json.message?.text || '').trim();
const m = text.match(/^\/(buy|sell)\s+([A-Za-z0-9.\-]+)\s+([\d.]+)\s+([\d.,]+)(?:\s+([\d.,]+))?$/i);
if (!m) return [{ json: { ok: false, chatId: $input.first().json.message?.chat?.id, reply: 'Format: /buy SYMBOL QTY PRICE [FEE]  e.g. /buy THYAO.IS 100 285.50' } }];
const n = v => Number(String(v || '0').replace(',', '.'));
return [{ json: {
  ok: true,
  chatId: $input.first().json.message.chat.id,
  date: new Date().toISOString().slice(0, 10),
  side: m[1].toUpperCase(),
  symbol: m[2].toUpperCase(),
  qty: n(m[3]),
  price: n(m[4]),
  fee: n(m[5]),
  enteredAt: new Date().toISOString()
}}];

// Build open positions with average cost and realized P/L (average cost method)
const trades = $input.all().map(i => i.json).sort((a, b) => String(a.enteredAt || a.date).localeCompare(String(b.enteredAt || b.date)));
const pos = {};
for (const t of trades) {
  const s = String(t.symbol || '').toUpperCase(); if (!s) continue;
  const qty = Number(t.qty), price = Number(t.price), fee = Number(t.fee || 0);
  const p = pos[s] || (pos[s] = { symbol: s, qty: 0, avgCost: 0, realized: 0, trades: 0 });
  p.trades++;
  if (String(t.side).toUpperCase() === 'BUY') {
    p.avgCost = (p.avgCost * p.qty + price * qty + fee) / (p.qty + qty);
    p.qty += qty;
  } else {
    p.realized += (price - p.avgCost) * qty - fee;
    p.qty -= qty;
    if (p.qty <= 0) { p.qty = 0; p.avgCost = 0; }
  }
}
return Object.values(pos).map(p => ({ json: { ...p, avgCost: Number(p.avgCost.toFixed(4)), realized: Number(p.realized.toFixed(2)) } }));

// Merge prices with positions, compute unrealized P/L
const positions = $('Calculate Positions').all().map(i => i.json);
return $input.all().map((item, idx) => {
  const p = positions[idx];
  const meta = item.json?.chart?.result?.[0]?.meta || {};
  const last = Number(meta.regularMarketPrice ?? NaN);
  const prevClose = Number(meta.chartPreviousClose ?? meta.previousClose ?? NaN);
  const marketValue = isNaN(last) ? null : Number((last * p.qty).toFixed(2));
  const unrealized = isNaN(last) || p.qty === 0 ? 0 : Number(((last - p.avgCost) * p.qty).toFixed(2));
  const unrealizedPct = p.avgCost && !isNaN(last) ? Number((((last - p.avgCost) / p.avgCost) * 100).toFixed(2)) : 0;
  const dayChangePct = !isNaN(last) && !isNaN(prevClose) && prevClose ? Number((((last - prevClose) / prevClose) * 100).toFixed(2)) : null;
  return { json: { ...p, currency: meta.currency || '', lastPrice: isNaN(last) ? null : last, dayChangePct, marketValue, unrealized, unrealizedPct, priceOk: !isNaN(last), updatedAt: new Date().toISOString() } };
});

// One Telegram summary for the day
const rows = $('Calculate P/L').all().map(i => i.json);
const open = rows.filter(r => r.qty > 0);
const fmt = n => (n > 0 ? '+' : '') + Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
const totalUnreal = open.reduce((s, r) => s + (r.unrealized || 0), 0);
const totalReal = rows.reduce((s, r) => s + (r.realized || 0), 0);
const lines = open.sort((a, b) => b.unrealized - a.unrealized).map(r => `${r.symbol}: ${r.qty} @ ${r.avgCost} | last ${r.lastPrice ?? 'n/a'} (${r.dayChangePct ?? '-'}% today) | P/L ${fmt(r.unrealized)} (${fmt(r.unrealizedPct)}%)`);
const missing = rows.filter(r => r.qty > 0 && !r.priceOk).map(r => r.symbol);
const text = `📊 Portfolio ${new Date().toISOString().slice(0, 10)}\n\n${lines.join('\n') || 'No open positions'}\n\nUnrealized: ${fmt(totalUnreal)}\nRealized (all time): ${fmt(totalReal)}` + (missing.length ? `\n\n⚠️ No price for: ${missing.join(', ')}` : '');
return [{ json: { text } }];
